Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow for inline compile-time values ---

    [TestMethod]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "10% tax")]
    [DataRow(5.50, 3, 0.0, 16.50, DisplayName = "No tax")]
    [DataRow(100.00, 1, 0.25, 125.00, DisplayName = "25% tax")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero price")]
    [DataRow(9.99, 0, 0.20, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        // DataRow doesn't support decimal literals, so cast from double
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1, 2, 0.1, "unitPrice")]
    [DataRow(10, -1, 0.1, "quantity")]
    [DataRow(10, 2, -0.1, "taxRate")]
    [DataRow(10, 2, 1.5, "taxRate")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData with ValueTuples for type safety ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10m, 90m),
        (200m, 25m, 150m),
        (50m, 0m, 50m),
        (80m, 100m, 0m),
        (0m, 50m, 0m),
    ];

    [TestMethod]
    [DataRow(-1.0)]
    [DataRow(101.0)]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRange(double discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }
}
```

**Key patterns used:**

| Pattern | Why |
|---------|-----|
| `[DataRow]` | Inline compile-time constants; quick for simple cases |
| `DynamicData` + ValueTuples | Type-safe, supports `decimal` literals directly (no double→decimal cast needed) |
| `Assert.ThrowsExactly<T>` | Modern exception testing (replaces `[ExpectedException]`) |
| `Assert.AreEqual(expected, actual)` | Expected first, actual second (avoids MSTEST0017) |
| `sealed` class | Performance best practice |
| `[TestMethod]` (not `[DataTestMethod]`) | Modern MSTest unifies both (avoids MSTEST0044) |

The `DataRow` approach requires `double` → `decimal` casts since `DataRow` doesn't support `decimal` literals. The `DynamicData` + ValueTuple approach avoids this limitation entirely — prefer it when you need exact decimal values.
